import type { Card } from "@/data/schema";
import type { Verdict } from "@/engine/draw";
import { ATOMIC_CHEEKS_LINES, CHEEKS_LINES, PEAK_LINES } from "@/engine/config";

export type HouseVerdict = Exclude<Verdict, null>;

/**
 * HOUSE VOICE — celebration taglines generated by the browser's built-in
 * on-device model (Chrome's Prompt API / Gemini Nano). Facts always come from
 * the data; the model only writes flavor. Every failure path falls back to the
 * hand-written pools, so the feature is strictly additive.
 */

// The Prompt API surfaces as a global constructor; old shapes used window.ai.
export function detectVoice(): boolean {
  const g = globalThis as { LanguageModel?: unknown; ai?: { languageModel?: unknown } };
  return typeof g.LanguageModel === "function" || !!g.ai?.languageModel;
}

type MaybeSession = { prompt: (input: string, opts?: { signal?: AbortSignal }) => Promise<string>; destroy?: () => void } | null;
type LanguageModelCtor = new (opts?: {
  initialPrompts?: { role: "system" | "user" | "assistant"; content: string }[];
  temperature?: number; topK?: number;
}) => MaybeSession;

function getCtor(): LanguageModelCtor | null {
  const g = globalThis as { LanguageModel?: unknown; ai?: { languageModel?: { create?: unknown } } };
  if (typeof g.LanguageModel === "function") return g.LanguageModel as LanguageModelCtor;
  // legacy window.ai.languageModel surface exposes create() rather than a constructor
  const legacy = g.ai?.languageModel as { create?: (opts?: object) => MaybeSession } | undefined;
  if (legacy && typeof legacy.create === "function") {
    return ((opts?: object) => legacy.create!(opts)) as unknown as LanguageModelCtor;
  }
  return null;
}

export const VOICE_SYSTEM = [
  "You write one-line verdict captions for a football card-pulling game.",
  "Voice: deadpan, PG-13, confident, funny. No emojis. No hashtags.",
  "PEAK lines are absurd larger-than-life boasts about the player.",
  "CHEEKS lines are short, brutal dismissals.",
  "ATOMIC CHEEKS lines are museum-grade despair about a historically rare bad pull.",
  "Never invent stats, teams, or facts about the player beyond what you are given.",
  "Output exactly ONE line. No quotes, no preamble, no sign-off. Max 90 characters.",
].join(" ");

export function anchorsFor(verdict: HouseVerdict, rand: () => number = Math.random): string[] {
  const pool = verdict === "peak" ? PEAK_LINES
    : verdict === "atomic" ? ATOMIC_CHEEKS_LINES : CHEEKS_LINES;
  const picks: string[] = [];
  // attempt cap: a degenerate rng must never spin here
  for (let i = 0; i < 60 && picks.length < Math.min(3, pool.length); i++) {
    const c = pool[Math.floor(rand() * pool.length)];
    if (typeof c === "string" && !picks.includes(c)) picks.push(c);
  }
  return picks;
}

export function voiceUserPrompt(card: Card, verdict: HouseVerdict, rand: () => number = Math.random): string {
  const label = verdict === "peak" ? "PEAK" : verdict === "atomic" ? "ATOMIC CHEEKS" : "CHEEKS";
  return [
    `Player: ${card.name} (${card.position}, ${card.team}, ${card.rating} OVR).`,
    `Verdict: ${label}.`,
    "Examples of the voice:",
    ...anchorsFor(verdict, rand).map((a) => `- ${a}`),
    "Write ONE new line in this voice about this player. Output only the line.",
  ].join("\n");
}

/** Clean and vet model output; null = unusable, use a pool line instead. */
export function validateLine(text: string): string | null {
  let s = (text ?? "").trim();
  s = s.replace(/^["'\u201c\u2018]+|["'\u201d\u2019]+$/g, "").trim();
  if (s.length < 8 || s.length > 120) return null;
  if (/[\n\r]/.test(s)) s = s.split(/[\n\r]/)[0].trim();
  if (s.length < 8 || s.length > 120) return null;
  const lower = s.toLowerCase();
  if (lower.startsWith("here's") || lower.startsWith("here is") || lower.includes("as an ai")
    || lower.startsWith("i'm sorry") || lower.startsWith("sure,") || lower.startsWith("okay,")) return null;
  // emoji / symbol clutter — the voice is typography-clean
  if (/[\u2190-\u2BFF\u{1F000}-\u{1FAFF}\u{FE0F}]/u.test(s)) return null;
  return s;
}

/** Which line lands on the celebration: generated (ai) or pool. */
export function chooseLine(
  generated: string | null,
  verdict: HouseVerdict,
  rand: () => number = Math.random,
): { line: string; ai: boolean } {
  if (generated) return { line: generated, ai: true };
  const pool = verdict === "peak" ? PEAK_LINES
    : verdict === "atomic" ? ATOMIC_CHEEKS_LINES : CHEEKS_LINES;
  return { line: pool[Math.floor(rand() * pool.length)], ai: false };
}

export interface VoiceOptions { timeoutMs?: number }

/**
 * Generate one house line for a pulled card. Returns a validated string, or
 * null for ANY failure (no API, model not resident, slow, dirty output).
 * Never triggers a model download — phone users' data is their own.
 */
export async function generateHouseLine(
  card: Card, verdict: HouseVerdict, opts: VoiceOptions = {},
): Promise<string | null> {
  const timeoutMs = opts.timeoutMs ?? 1500;
  const Ctor = getCtor();
  if (!Ctor) return null;
  try {
    const g = globalThis as { LanguageModel?: { availability?: () => Promise<string> } };
    if (typeof g.LanguageModel?.availability === "function") {
      const a = await g.LanguageModel.availability();
      // both vocabularies: only generate when the model is already on device
      if (a !== "available" && a !== "readily") return null;
    }
    const session = await new Ctor({ initialPrompts: [{ role: "system", content: VOICE_SYSTEM }] });
    if (!session || typeof session.prompt !== "function") return null;
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), timeoutMs);
    try {
      const raw = await session.prompt(voiceUserPrompt(card, verdict), { signal: ctrl.signal });
      return validateLine(raw);
    } finally {
      clearTimeout(timer);
      try { session.destroy?.(); } catch { /* best effort */ }
    }
  } catch {
    return null;
  }
}
